# Let's manually identify changed pairs since we can't import the library
inputs = ['gfc', 'je', 'yigjud', 'zwiedy', 'jjwwv']
outputs = ['gfc', 'je', 'yiubgjud', 'zwdzdy', 'jjwwv']

changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

print("\nAnalyzing differences:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' vs '{outp}'")
    # Find where they differ
    min_len = min(len(inp), len(outp))
    diff_pos = -1
    for i in range(min_len):
        if inp[i] != outp[i]:
            diff_pos = i
            break
    if diff_pos == -1:
        if len(inp) != len(outp):
            diff_pos = min_len
    print(f"    First difference at position {diff_pos}")

